import{_ as a,o as i,c as l,e as s}from"./app-6c9584fa.js";const o={};function n(d,e){return i(),l("div",null,[...e[0]||(e[0]=[s(`<h1 id="_6-5-商业化闭环-并发限流、token-计费与支付网关集成" tabindex="-1"><a class="header-anchor" href="#_6-5-商业化闭环-并发限流、token-计费与支付网关集成" aria-hidden="true">#</a> 6.5 商业化闭环：并发限流、Token 计费与支付网关集成</h1><p>本节目标：让项目具备“可持续运营”的商业化能力：能控制滥用、能统计成本、能按套餐/用量收费、能闭环对账。这里的关键不是“接上 Stripe 就完了”，而是建立一套<strong>可审计的成本账本 + 可执行的配额策略 + 稳定的支付与订阅状态机</strong>。</p><p>同时说明现状：<code>ai-data-analyzer</code> 当前后端依赖中并未包含 Stripe SDK、鉴权/会员体系也未完成（6.4 才补齐）。因此 6.5 的内容以“可落地的实现步骤与结构设计”为主，便于你按章节逐步把代码做出来。</p><hr><h2 id="_6-5-1-先把问题讲清楚-你到底在卖什么" tabindex="-1"><a class="header-anchor" href="#_6-5-1-先把问题讲清楚-你到底在卖什么" aria-hidden="true">#</a> 6.5.1 先把问题讲清楚：你到底在卖什么</h2><p>数据分析 AI Agent 的成本通常来自三块：</p><ol><li>LLM 调用成本：输入/输出 tokens（可能还有工具调用 tokens）</li><li>执行器成本：6.2 的代码沙盒执行时间、CPU、内存、存储（产物/日志）</li><li>基础设施成本：队列、数据库、向量库检索、带宽</li></ol><p>商业化的本质是：把这些成本转化为用户可理解的计费单位，并提供可控的配额与限流。</p><p>典型计费单位（可组合）：</p><ul><li>按请求数（calls）</li><li>按 token 数（tokens）</li><li>按执行器用量（exec seconds / job seconds）</li><li>按存储（datasets / artifacts / vector chunks）</li></ul><p>建议第一版选择“<strong>订阅 + 额度</strong>”作为主模型：</p><ul><li>Free：每日/每月固定额度（例如 tokens + 次数），超了不可用或降级</li><li>Pro：更高额度，允许更大文件、更高并发</li><li>Team：多 workspace 成员、审计与导出</li></ul><hr><h2 id="_6-5-2-成本账本-billing-ledger-可审计比-算得准-更重要" tabindex="-1"><a class="header-anchor" href="#_6-5-2-成本账本-billing-ledger-可审计比-算得准-更重要" aria-hidden="true">#</a> 6.5.2 成本账本（Billing Ledger）：可审计比“算得准”更重要</h2><p>很多项目在计费上踩坑的原因是：只记录“总数”，不记录“每一笔明细”。一旦用户质疑账单、或者出现重试/失败，你就对不上账。</p><p>正确做法是建立账本（Ledger）：</p><h3 id="账本需要记录什么" tabindex="-1"><a class="header-anchor" href="#账本需要记录什么" aria-hidden="true">#</a> 账本需要记录什么</h3><p>至少记录三类事件：</p><ol><li>LLMUsage：一次模型调用的 tokens 与费用估算</li><li>ExecUsage：一次执行器任务的资源用量（duration/cpu/memory）</li><li>StorageUsage：存储增量（上传的数据/生成的 artifacts/向量 chunks）</li></ol><p>并且每条记录都要能关联到：</p><ul><li><code>workspace_id</code>（租户）</li><li><code>user_id</code>（发起者）</li><li><code>analysis_id</code> / <code>job_id</code>（业务事件）</li><li><code>provider</code>（openai/claude/…）</li></ul><h3 id="建议的最小表结构-概念层" tabindex="-1"><a class="header-anchor" href="#建议的最小表结构-概念层" aria-hidden="true">#</a> 建议的最小表结构（概念层）</h3><ul><li><code>billing_ledger</code><ul><li><code>id</code></li><li><code>workspace_id</code></li><li><code>user_id</code></li><li><code>event_type</code>：<code>llm | exec | storage</code></li><li><code>event_key</code>：用于幂等（例如 <code>analysisId:stepId:attempt</code>）</li><li><code>amount</code>：货币金额（可选，第一版也可以不算钱只算单位）</li><li><code>units</code>：JSON（tokens/duration/storageBytes）</li><li><code>metadata</code>：provider、model、promptHash、artifactRefs</li><li><code>created_at</code></li></ul></li></ul><p>这里的关键是 <code>event_key</code>：当 BullMQ 重试或网络抖动导致重复写入时，账本不会被重复计费。</p><hr><h2 id="_6-5-3-token-计量-如何-准确-地拿到-tokens" tabindex="-1"><a class="header-anchor" href="#_6-5-3-token-计量-如何-准确-地拿到-tokens" aria-hidden="true">#</a> 6.5.3 Token 计量：如何“准确”地拿到 tokens</h2><h3 id="openai" tabindex="-1"><a class="header-anchor" href="#openai" aria-hidden="true">#</a> OpenAI</h3><p>在多数 SDK 中，返回体会提供 usage（输入/输出/总 token）。需要把它贯穿到 6.1 的每一步 task 上：</p><ul><li>Router 调用一次，记一次 usage</li><li>Data Coder 可能多次重试，必须把 attempt 维度记到 event_key</li><li>Reviewer/Writer 同理</li></ul><h3 id="anthropic-claude" tabindex="-1"><a class="header-anchor" href="#anthropic-claude" aria-hidden="true">#</a> Anthropic（Claude）</h3><p>同样会有 token/usage 字段（命名略有差异），原则相同：必须在统一的“UsageExtractor”层做适配。</p><h3 id="工程建议-统一一个-usage-适配层" tabindex="-1"><a class="header-anchor" href="#工程建议-统一一个-usage-适配层" aria-hidden="true">#</a> 工程建议：统一一个 Usage 适配层</h3><p>无论你使用哪个 LLMService，都让它返回一个统一结构：</p><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">interface</span> <span class="token class-name">LLMCallMeta</span> <span class="token punctuation">{</span>
  provider<span class="token operator">:</span> <span class="token string">&#39;openai&#39;</span> <span class="token operator">|</span> <span class="token string">&#39;anthropic&#39;</span> <span class="token operator">|</span> <span class="token string">&#39;local&#39;</span><span class="token punctuation">;</span>
  model<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>
  usage<span class="token operator">?</span><span class="token operator">:</span> <span class="token punctuation">{</span> input<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span> output<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span> total<span class="token operator">:</span> <span class="token builtin">number</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这样你的账本与配额模块就不用关心底层 SDK 的差异。</p><hr><h2 id="_6-5-4-配额-quota-与策略-policy-让-能用-不能用-降级-有依据" tabindex="-1"><a class="header-anchor" href="#_6-5-4-配额-quota-与策略-policy-让-能用-不能用-降级-有依据" aria-hidden="true">#</a> 6.5.4 配额（Quota）与策略（Policy）：让“能用/不能用/降级”有依据</h2><p>只有账本还不够，你还需要“可执行的策略”，决定用户是否允许发起新任务，以及当超额时怎么处理。</p><h3 id="step-1-定义额度维度" tabindex="-1"><a class="header-anchor" href="#step-1-定义额度维度" aria-hidden="true">#</a> Step 1：定义额度维度</h3><p>建议至少三维：</p><ul><li><code>monthly_tokens</code></li><li><code>monthly_requests</code></li><li><code>concurrent_jobs</code></li></ul><p>进阶可加：</p><ul><li><code>max_file_size_mb</code></li><li><code>max_rows_per_dataset</code></li><li><code>max_artifacts_per_month</code></li></ul><h3 id="step-2-策略执行点-拦截在哪里" tabindex="-1"><a class="header-anchor" href="#step-2-策略执行点-拦截在哪里" aria-hidden="true">#</a> Step 2：策略执行点（拦截在哪里）</h3><p>推荐三处拦截：</p><ol><li>API 接口入口：上传/发起分析时检查配额（快速拒绝）</li><li>入队前：BullMQ enqueue 前检查（避免排队浪费）</li><li>Worker 执行前：最后一道闸（防止并发突刺导致突破）</li></ol><p>并且要明确三种结果：</p><ul><li>allow：允许执行</li><li>deny：拒绝并返回明确错误（提示升级套餐）</li><li>degrade：降级执行（例如不生成 3D 图表、减少 TopK、缩短报告）</li></ul><p>降级策略能显著提升免费用户体验，也能降低运营压力。</p><hr><h2 id="_6-5-5-redis-限流-保护系统、降低滥用" tabindex="-1"><a class="header-anchor" href="#_6-5-5-redis-限流-保护系统、降低滥用" aria-hidden="true">#</a> 6.5.5 Redis 限流：保护系统、降低滥用</h2><p>你的项目已经依赖 Redis（BullMQ/Cache），因此限流可以直接复用 Redis。</p><h3 id="最小可用的限流-按用户-按-ip-的滑动窗口" tabindex="-1"><a class="header-anchor" href="#最小可用的限流-按用户-按-ip-的滑动窗口" aria-hidden="true">#</a> 最小可用的限流：按用户/按 IP 的滑动窗口</h3><p>典型规则：</p><ul><li>Free：每分钟 5 次分析请求</li><li>Pro：每分钟 30 次</li><li>Team：更高 + 更高并发</li></ul><p>实现要点（概念层）：</p><ul><li>key：<code>rl:{workspaceId}:{userId}:{route}:{window}</code></li><li>value：计数器 + 过期时间（TTL）</li></ul><h3 id="并发限制-防止-同时开-100-个任务" tabindex="-1"><a class="header-anchor" href="#并发限制-防止-同时开-100-个任务" aria-hidden="true">#</a> 并发限制：防止“同时开 100 个任务”</h3><p>除了 API 限流，还要做并发限制（特别是 Worker 侧）：</p><ul><li><code>concurrent_jobs</code> 作为配额维度</li><li>Worker 执行前检查当前 workspace 正在 running 的 job 数量</li></ul><hr><h2 id="_6-5-6-支付与订阅-stripe-接入的正确姿势-状态机优先" tabindex="-1"><a class="header-anchor" href="#_6-5-6-支付与订阅-stripe-接入的正确姿势-状态机优先" aria-hidden="true">#</a> 6.5.6 支付与订阅：Stripe 接入的正确姿势（状态机优先）</h2><p>支付系统的核心不是“前端付钱”，而是“后端可信地知道订阅状态”。</p><h3 id="step-1-定义订阅实体与状态" tabindex="-1"><a class="header-anchor" href="#step-1-定义订阅实体与状态" aria-hidden="true">#</a> Step 1：定义订阅实体与状态</h3><p>你至少需要在 DB 里保存：</p><ul><li><code>stripe_customer_id</code></li><li><code>stripe_subscription_id</code></li><li><code>plan</code>（free/pro/team）</li><li><code>status</code>（active/past_due/canceled/trialing）</li><li><code>current_period_end</code></li></ul><p>并把它归属到 <code>workspace_id</code>（不是 user）。</p><h3 id="step-2-前端结账页-checkout" tabindex="-1"><a class="header-anchor" href="#step-2-前端结账页-checkout" aria-hidden="true">#</a> Step 2：前端结账页（Checkout）</h3><ul><li>用户在某个 workspace 下升级套餐</li><li>创建 Stripe Checkout Session</li><li>支付完成后跳回前端 success URL</li></ul><h3 id="step-3-webhook-驱动的订阅同步-必须" tabindex="-1"><a class="header-anchor" href="#step-3-webhook-驱动的订阅同步-必须" aria-hidden="true">#</a> Step 3：Webhook 驱动的订阅同步（必须）</h3><p>真正可信的状态更新来自 Stripe Webhook，而不是前端跳转。</p><p>你需要处理至少这些事件：</p><ul><li><code>checkout.session.completed</code></li><li><code>invoice.paid</code></li><li><code>invoice.payment_failed</code></li><li><code>customer.subscription.updated</code></li><li><code>customer.subscription.deleted</code></li></ul><p>处理逻辑：</p><ul><li>更新订阅状态</li><li>变更 plan 与额度</li><li>记录账本（付款事件也可以记入 ledger，便于对账）</li></ul><h3 id="step-4-对账与幂等" tabindex="-1"><a class="header-anchor" href="#step-4-对账与幂等" aria-hidden="true">#</a> Step 4：对账与幂等</h3><p>Webhook 可能重复投递，因此：</p><ul><li>事件 id 必须做幂等（存一张 <code>webhook_events</code> 或直接利用 ledger event_key）</li><li>任意一次处理失败要可重试（BullMQ 也可以用于 webhook 异步处理）</li></ul><hr><h2 id="_6-5-7-与-6-1-6-4-的联动-这不是独立章节" tabindex="-1"><a class="header-anchor" href="#_6-5-7-与-6-1-6-4-的联动-这不是独立章节" aria-hidden="true">#</a> 6.5.7 与 6.1~6.4 的联动：这不是独立章节</h2><p>6.5 的计费与限流要与前面章节真正打通：</p><ul><li>6.1：每一步 agent task 产出 tokens/attempt，写入 ledger（可追溯到 step）</li><li>6.2：执行器的 duration/cpu/memory 写入 exec ledger，并纳入配额</li><li>6.3：向量库的 chunk 数量与 embedding 调用也要计量（否则成本黑洞）</li><li>6.4：所有计费、订阅、额度的归属单位是 workspace（多租户边界）</li></ul><p>把这些接起来，你的系统就具备了“能规模化运营”的能力。</p><hr><h2 id="_6-5-8-验收标准-商业化闭环最小可用版本-mvp" tabindex="-1"><a class="header-anchor" href="#_6-5-8-验收标准-商业化闭环最小可用版本-mvp" aria-hidden="true">#</a> 6.5.8 验收标准：商业化闭环最小可用版本（MVP）</h2><ul><li>免费/付费套餐能区分额度，并在 API 与 Worker 两处生效</li><li>每次 LLM 调用都能记录 usage 明细，并可按 workspace 聚合查询</li><li>Redis 限流可用，能有效阻挡恶意高频请求</li><li>Stripe 订阅状态以 Webhook 为准，并能正确同步到 workspace</li><li>账本具备幂等键，重试不会重复计费</li></ul>`,86)])])}const t=a(o,[["render",n],["__file","6.5 商业化闭环：并发限流与计费集成.html.vue"]]);export{t as default};
